fn merge_sort<T: Ord + Send>(v: &mut [T]) {
    if v.len() < 1024 { v.sort(); return; }        // base case
    let mid = v.len() / 2;
    let (lo, hi) = v.split_at_mut(mid);            // disjoint mutable halves
    rayon::join(|| merge_sort(lo), || merge_sort(hi));  // fork + join
    merge_runs(v);                                 // combine
}
